<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/inventory-list-data.php';
require_once __DIR__ . '/../design-system/inventory-samples.php';
$connection = cssrInventorySampleConnection();
$checks = 0;
function inventoryExpect($actual, $expected, string $label): void {
    global $checks; $checks++;
    if ($actual !== $expected) throw new RuntimeException($label . ': ' . json_encode($actual));
}
$all = cssrInventoryList($connection, []);
inventoryExpect($all['summary'], ['total'=>28,'available'=>18,'low'=>6,'out'=>4,'invalid'=>0], 'Summary includes all filtered records, not just one page');
inventoryExpect(count($all['rows']), 10, 'Default page size');
inventoryExpect($all['pages'], 3, 'Total pages');
inventoryExpect([$all['first'],$all['last']], [1,10], 'Visible range');
$next = cssrInventoryList($connection, ['page'=>2]);
inventoryExpect(count(array_intersect(array_column($all['rows'],'id'),array_column($next['rows'],'id'))), 0, 'Stable pages do not overlap');
inventoryExpect(cssrInventoryList($connection,['page'=>99999])['filters']['page'], 3, 'Out-of-range page clamps to last page');
inventoryExpect(count(cssrInventoryList($connection,['per_page'=>25,'page'=>2])['rows']), 3, 'Second page at 25 rows');
inventoryExpect(cssrInventoryList($connection,['q'=>'gloves'])['summary']['total'], 1, 'Search item name');
inventoryExpect(cssrInventoryList($connection,['q'=>'CSSR-0002'])['rows'][0]['item_name'], 'Bandage scissors', 'Search item code');
inventoryExpect(cssrInventoryList($connection,['q'=>'MEDICAL INSTRUMENTS'])['summary']['total'], 5, 'Search classification');
inventoryExpect(cssrInventoryList($connection,['classification'=>'MEDICAL INSTRUMENTS','stock_status'=>'AVAILABLE'])['summary']['total'], 3, 'Combined classification and status');
inventoryExpect(cssrInventoryList($connection,['procurement_type'=>'DONATION'])['summary']['total'], 9, 'Procurement filter uses inbound metadata');
inventoryExpect(cssrInventoryList($connection,['storage_location'=>'STORAGE ROOM 1'])['summary']['total'], 9, 'Storage filter');
inventoryExpect(cssrInventoryList($connection,['storage_location'=>'STORAGE ROOM 1','procurement_type'=>'REGULAR'])['summary']['total'], 0, 'Filters combine with AND');
inventoryExpect(cssrInventoryList($connection,['stock_status'=>'INVALID'])['summary']['total'], 0, 'Missing metadata does not make nonnegative stock invalid');
inventoryExpect(cssrInventoryList($connection,['q'=>'CSSR-0003'])['rows'][0]['stock_status'], 'AVAILABLE', 'Positive quantity with missing unit is available');
$connection->exec("UPDATE item_lots SET quantity_available=0 WHERE item_id=3; UPDATE items SET minimum_stock=-1 WHERE id=3");
inventoryExpect(cssrInventoryList($connection,['q'=>'CSSR-0003'])['rows'][0]['stock_status'], 'OUT OF STOCK', 'Zero quantity is out of stock even with missing metadata or negative reorder level');
$connection->exec('UPDATE item_lots SET quantity_available=150 WHERE item_id=3; UPDATE items SET minimum_stock=50 WHERE id=3');
inventoryExpect(cssrInventoryList($connection,['q'=>"' OR 1=1 --"])['summary']['total'], 0, 'Search does not change SQL structure');
inventoryExpect(cssrInventoryList($connection,['q'=>'%'])['summary']['total'], 1, 'Search percent only matches Alcohol 70%, not every item');
inventoryExpect(cssrInventoryList($connection,['q'=>'_'])['summary']['total'], 0, 'Search underscore is literal');
inventoryExpect(cssrInventoryList($connection,['q'=>[],'page'=>[],'per_page'=>[]])['filters'], cssrInventoryFilters([]), 'Array inputs handled safely');
inventoryExpect(cssrInventoryList($connection,['q'=>'missing item','page'=>2])['first'], 0, 'Empty results range starts at zero');
inventoryExpect(cssrInventoryList($connection,['q'=>'gloves','page'=>2])['filters']['page'], 1, 'Filter narrows the valid page range');
$url = cssrInventoryUrl('items.php',cssrInventoryFilters(['q'=>'gloves','classification'=>'MEDICAL SUPPLIES','per_page'=>25]),['page'=>2]);
parse_str((string)parse_url($url,PHP_URL_QUERY),$urlParams);
inventoryExpect([$urlParams['q'],$urlParams['classification'],$urlParams['per_page'],$urlParams['page']], ['gloves','MEDICAL SUPPLIES','25','2'], 'Pagination URLs preserve filters and page size');
$connection->exec("INSERT INTO stock_in VALUES(1,'DONATION'); INSERT INTO item_lots VALUES(1,20,'STORAGE ROOM 1')");
$mixed = cssrInventoryList($connection,['q'=>'CSSR-0001','procurement_type'=>'DONATION','storage_location'=>'STORAGE ROOM 1']);
inventoryExpect($mixed['summary']['total'], 1, 'Multiple lots and receipts do not duplicate items');
inventoryExpect((int)$mixed['rows'][0]['current_stock'], 20, 'Selected room displays only its own balance');
$cssrOnly = cssrInventoryList($connection,['q'=>'CSSR-0001','storage_location'=>'CSSR']);
inventoryExpect((int)$cssrOnly['rows'][0]['current_stock'], 130, 'CSSR excludes the same item stock in Storage Room 1');
$connection->exec("UPDATE item_lots SET storage_location='STORAGE ROOM 1' WHERE item_id=2");
inventoryExpect(cssrInventoryList($connection,['q'=>'CSSR-0002','storage_location'=>'CSSR'])['summary']['total'], 0, 'Storage-only item is absent when CSSR is selected');
$connection->exec("UPDATE items SET bin_location='CSSR STORAGE' WHERE id=2");
inventoryExpect(in_array('CSSR STORAGE',cssrInventoryList($connection,[])['options']['storage_location'],true), false, 'Location selector removes the old CSSR STORAGE label');
$connection->exec('UPDATE item_lots SET quantity_available=50 WHERE item_id=2');
inventoryExpect(cssrInventoryList($connection,['q'=>'CSSR-0002'])['rows'][0]['stock_status'], 'AVAILABLE', 'Reorder equality matches approved dashboard');
$connection->exec('UPDATE item_lots SET quantity_available=-1 WHERE item_id=2');
inventoryExpect(cssrInventoryList($connection,['q'=>'CSSR-0002'])['rows'][0]['stock_status'], 'INVALID', 'Negative balance is invalid');
$connection->exec("UPDATE items SET status='Inactive' WHERE id=2");
inventoryExpect(cssrInventoryList($connection,['q'=>'CSSR-0002'])['summary']['total'], 0, 'Inactive items excluded from active inventory');
$connection->exec('DELETE FROM item_lots WHERE item_id=4');
inventoryExpect((int)cssrInventoryList($connection,['q'=>'CSSR-0004'])['rows'][0]['current_stock'], 24, 'Legacy item balance used only if no lots exist');
inventoryExpect(cssrInventoryList($connection,['q'=>'CSSR-0004','storage_location'=>'CSSR'])['summary']['total'], 1, 'Legacy bin location fallback');
echo "Passed {$checks} inventory data checks in an isolated in-memory database.\n";
